surface.onkeydown=e=>{if(!learned||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const step=e.shiftKey?.05:.015;position={x:Math.max(0,Math.min(1,position.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0))),y:Math.max(0,Math.min(1,position.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)))};if(playing)master.gain.setTargetAtTime(+$('#volume').value/100,ctx.currentTime,.025);updatePosition()};
$('#anchors').onclick=e=>{const b=e.target.closest('[data-select]');if(!b||b.disabled)return;selected=+b.dataset.select;if(learned){const a=anchors.find(a=>a.id===selected);position=a.points[Math.floor(a.points.length/2)];updatePosition()}else render()};
function updatePosition(){if(!learned)return;const w=weightsAt(anchors,position);node?.port.postMessage({model:synthModel(anchors,w,position)});renderScene();renderMeters()}
async function audio(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=+$('#volume').value/100;master.connect(ctx.destination)}await ctx.resume()}
function stopAudio(){if(node){node.disconnect();node.port.close();node=null}playing=false}
async function startAudio(){if(!learned)return;await audio();if(!moduleReady)moduleReady=ctx.audioWorklet.addModule('plane-worklet.js').catch(e=>{moduleReady=null;throw e});await moduleReady;stopAudio();node=new AudioWorkletNode(ctx,'plane-morph',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[1],processorOptions:{model:synthModel(anchors,weightsAt(anchors,position),position)}});node.onprocessorerror=()=>{stopAudio();render();status('Audio stopped. Your landscape is kept; press Start exploring to retry.')};node.connect(master);master.gain.setTargetAtTime(+$('#volume').value/100,ctx.currentTime,.03);playing=true;render();status('Move inside the canvas to listen. Moving outside quiets the sound.');}
function bytes(buffer){return{rate:buffer.sampleRate,channels:Array.from({length:buffer.numberOfChannels},(_,c)=>buffer.getChannelData(c).slice())}}
function disarm(){clearTimeout(armTimer);armedStream?.getTracks().forEach(t=>t.stop());armedStream=null;}
async function prepareMic(){if(armedStream){disarm();render();return}if(arming||recording||pendingRecord||learned)return;if(!navigator.mediaDevices?.getUserMedia){status('Microphone unavailable. You can still upload recordings.');return}const token=epoch;arming=true;render();status('Allow the microphone. Then draw and sing together.');try{await audio();const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(token!==epoch){stream.getTracks().forEach(t=>t.stop());return}armedStream=stream;armTimer=setTimeout(()=>{disarm();render();status('Microphone readiness expired. Enable mic again when you’re ready to draw.')},45000);status('Microphone ready. Draw while making your sound; hold nearly still for a point-like sound.')}catch(e){if(token===epoch)status(e.name==='NotAllowedError'?'Microphone access was denied. Allow it in your browser to record.':'Could not enable the microphone. Try again.')}finally{if(token===epoch){arming=false;render()}}}
